/// working copy, import git refs, each its own operation.
///
/// Deviation from the CLI: a new file over
/// `snapshot.max-new-file-size` is a [`FilesTooLarge`] error,
/// where the `jj` command warns and goes on. A verb that went
/// on would work on a working copy missing the file, and push
/// would commit without it.
pub fn snapshot(&mut self) -> Result<()> {
    let files = self.snapshot_with(None)?;
    if files.is_empty() {
        return Ok(());
    }
    let repo = self.workspace.workspace_root().to_path_buf();
    Err(Box::new(FilesTooLarge {
        agent_repo: crate::common::is_bot_dir(&repo),
        limit: self.max_new_file_size()?,
        repo,
        files,
    }))
}

/// `snapshot.max-new-file-size` in bytes, its 0 read as no
/// limit, as the CLI reads it.
fn max_new_file_size(&self) -> Result<u64> {
    let HumanByteSize(max) = self
        .settings
        .get_value_with("snapshot.max-new-file-size", TryInto::try_into)?;
    Ok(if max == 0 { u64::MAX } else { max })
}

/// `snapshot`, with the new-file size limit overridden when
/// `max_new_file_size` is `Some`, returning the new files the
/// limit left untracked, with their sizes.
fn snapshot_with(&mut self, max_new_file_size: Option<u64>) -> Result<Vec<(String, u64)>> {
    let _lock = self.lock_git()?;
    // Reload at head (under the lock when colocated): sessions
    // outlive single verbs in a `Context`, and another process
    // or a spawned `jj` may have committed operations since the
    // open or the previous verb.
    self.repo = self.workspace.repo_loader().load_at_head().block_on()?;
    if self.colocated {
        self.import_git_head()?;
    }
    let too_large = self.snapshot_working_copy(max_new_file_size)?;
    if self.colocated {
        self.import_git_refs()?;
    }
    Ok(too_large)
}

/// Import a moved git HEAD (someone ran plain git here): check
/// out the new head and reset the working-copy state to it.
fn import_git_head(&mut self) -> Result<()> {
    let mut tx = self.repo.start_transaction();
    tag_run(&mut tx);
    git::import_head(
        tx.repo_mut(),
        self.workspace.workspace_name(),
        self.workspace.workspace_root(),
    )
    .block_on()?;
    if !tx.repo().has_changes() {
        return Ok(());
    }
    debug!("git HEAD moved; importing");
    let new_git_head = tx
        .repo()
        .view()
        .git_head(self.workspace.workspace_name())
        .clone();
    if let Some(new_git_head_id) = new_git_head.as_normal() {
        let name = self.workspace.workspace_name().to_owned();
        let head_commit = tx.repo().store().get_commit(new_git_head_id)?;
        let wc_commit = tx.repo_mut().check_out(name, &head_commit).block_on()?;
        let mut locked_ws = self.workspace.start_working_copy_mutation().block_on()?;
        // The git command that moved HEAD updated the files too,
        // so reset the state without touching the working copy.
        locked_ws.locked_wc().reset(&wc_commit).block_on()?;
        tx.repo_mut().rebase_descendants().block_on()?;
        self.repo = tx.commit("import git head").block_on()?;
        locked_ws.finish(self.repo.op_id().clone()).block_on()?;
    } else {
        tx.repo_mut().rebase_descendants().block_on()?;
        self.repo = tx.commit("import git head").block_on()?;
    }
    Ok(())
}

